(@u_staff,@u_nadia,'Re: Tanya SOP retur','Bisa, cari nomor notanya di Riwayat Transaksi. Ada di knowledge retur.',1,TIMESTAMP(CURDATE() - INTERVAL 21 DAY, '15:50:00')),
(@u_manajer,@u_bagus,'Chiller ikan','Bagus, suhu chiller ikan kemarin naik. Tolong cek pagi ini.',1,TIMESTAMP(CURDATE() - INTERVAL 16 DAY, '13:20:00')),
(@u_bagus,@u_manajer,'Re: Chiller ikan','Sudah normal Bu, pintunya kurang rapat. Sudah saya catat di formulir.',1,TIMESTAMP(CURDATE() - INTERVAL 16 DAY, '15:50:00')),
(@u_manajer,@u_nadia,'Poster promo terlambat','Nadia, papan informasi promo belum diperbarui. Mohon diselesaikan hari ini.',1,TIMESTAMP(CURDATE() - INTERVAL 42 DAY, '15:50:00')),
(@u_manajer,@u_dimas,'Mesin EDC cadangan','Dimas, uji coba EDC cadangan sudah lewat tenggat. Ada kendala?',1,TIMESTAMP(CURDATE() - INTERVAL 26 DAY, '13:20:00')),
(@u_dimas,@u_manajer,'Re: Mesin EDC cadangan','Maaf Bu, kabel dayanya baru datang. Hari ini saya selesaikan.',1,TIMESTAMP(CURDATE() - INTERVAL 25 DAY, '17:30:00')),
(@u_manajer,@u_bagus,'Tugas menumpuk','Bagus, ada beberapa tugas gudang yang belum selesai. Mana yang perlu dibantu?',0,TIMESTAMP(CURDATE() - INTERVAL 6 DAY, '17:30:00')),
(@u_staff,@u_manajer,'Usulan promo produk kurang laku','Bu, madu hutan dan lilin aromaterapi hampir tidak terjual. Usul dibuat bundling.',0,TIMESTAMP(CURDATE() - INTERVAL 5 DAY, '15:50:00')),
(@u_nadia,@u_manajer,'Jadwal piket','Bu, draf jadwal piket sudah saya susun. Mohon dicek.',0,TIMESTAMP(CURDATE() - INTERVAL 4 DAY, '10:05:00')),
(@u_manajer,@u_staff,'Display promo awal bulan','Rafa, rak ujung tolong dikosongkan besok untuk promo.',1,TIMESTAMP(CURDATE() - INTERVAL 2 DAY, '10:05:00')),
(@u_admin,@u_manajer,'Pencadangan sistem','Pencadangan mingguan selesai tanpa kendala.',0,TIMESTAMP(CURDATE() - INTERVAL 1 DAY, '15:50:00'));
INSERT IGNORE INTO kategori_kms(nama,deskripsi,ikon) VALUES('Keamanan Pangan','Standar kebersihan, penyimpanan, dan kedaluwarsa produk','🧼');
INSERT INTO artikel_kms(judul,id_kategori,ringkasan,isi,id_penulis,status,visibilitas,id_reviewer,catatan_review,versi,dilihat,dibuat,diperbarui) VALUES
('Cara Menangani Retur Barang dari Pelanggan',@k_ops,'Langkah standar kasir saat pelanggan mengembalikan barang yang rusak atau tidak sesuai.','1. Minta pelanggan menunjukkan struk pembelian (maksimal 3 hari setelah transaksi).\n2. Periksa kondisi barang: kemasan, tanggal kedaluwarsa, dan kelengkapan.\n3. Cocokkan nomor nota di menu Riwayat Transaksi.\n4. Catat retur di formulir retur (menu Dokumen > Formulir).\n5. Kembalikan dana sesuai metode bayar awal.\n6. Letakkan barang retur di rak karantina dan laporkan ke manajer.',@u_staff,'published','internal',@u_manajer,'Sudah lengkap.',2,96,TIMESTAMP(CURDATE() - INTERVAL 50 DAY, '10:30:00'),TIMESTAMP(CURDATE() - INTERVAL 47 DAY, '14:10:00')),
('SOP Pengecekan Tanggal Kedaluwarsa Produk',@k_pangan,'Cara memeriksa dan menarik produk yang mendekati atau melewati tanggal kedaluwarsa.','1. Setiap Senin dan Kamis, periksa tanggal di rak susu, roti, dan daging.\n2. Produk dengan sisa masa simpan kurang dari 3 hari diberi label promo.\n3. Produk kedaluwarsa segera ditarik dari rak.\n4. Catat penarikan lewat menu Stok Produk > Koreksi.',@u_admin,'published','internal',@u_admin,NULL,1,74,TIMESTAMP(CURDATE() - INTERVAL 48 DAY, '10:30:00'),TIMESTAMP(CURDATE() - INTERVAL 48 DAY, '14:10:00')),
('Panduan Menerima Pembayaran QRIS',@k_ti,'Langkah kasir menerima pembayaran QRIS dan memastikan dana masuk.','1. Pilih metode QRIS di menu Kasir.\n2. Tunjukkan kode QR toko ke pelanggan.\n3. Minta pelanggan menunjukkan bukti berhasil.\n4. Cocokkan nominal dengan total belanja.\n5. Tekan Bayar & Cetak Nota.',@u_manajer,'published','internal',@u_manajer,NULL,2,88,TIMESTAMP(CURDATE() - INTERVAL 45 DAY, '10:30:00'),TIMESTAMP(CURDATE() - INTERVAL 12 DAY, '14:10:00')),
('Menerapkan FIFO di Gudang',@k_ops,'Cara menyusun barang agar stok lama keluar lebih dulu.','Letakkan barang baru di belakang barang lama.\nTulis tanggal terima di setiap dus.\nPeriksa tanggal kedaluwarsa saat menyusun.\nLaporkan dus yang rusak ke manajer.',@u_bagus,'published','internal',@u_manajer,'Bagus, mudah dipahami.',1,41,TIMESTAMP(CURDATE() - INTERVAL 43 DAY, '10:30:00'),TIMESTAMP(CURDATE() - INTERVAL 43 DAY, '14:10:00')),
('Menghadapi Pelanggan yang Komplain',@k_ops,'Teknik sederhana menenangkan pelanggan dan menyelesaikan keluhan.','Dengarkan sampai selesai tanpa memotong.\nUlangi inti keluhan untuk memastikan paham.\nTawarkan solusi yang sesuai SOP: tukar, retur, atau panggil manajer.\nCatat keluhan di laporan komplain.',@u_nadia,'published','internal',@u_manajer,NULL,2,67,TIMESTAMP(CURDATE() - INTERVAL 38 DAY, '10:30:00'),TIMESTAMP(CURDATE() - INTERVAL 34 DAY, '14:10:00')),
('Menjaga Suhu Chiller Daging dan Ikan',@k_pangan,'Standar suhu dan cara mencatatnya setiap hari.','Suhu chiller dijaga 0 sampai 4 derajat Celsius.\nCatat suhu pagi dan sore di formulir.\nJika suhu di atas 5 derajat lebih dari 30 menit, pindahkan produk dan lapor manajer.\nBersihkan chiller seminggu sekali.',@u_bagus,'published','internal',@u_manajer,NULL,1,38,TIMESTAMP(CURDATE() - INTERVAL 36 DAY, '10:30:00'),TIMESTAMP(CURDATE() - INTERVAL 36 DAY, '14:10:00')),
('Aturan Tukar Shift dan Izin',@k_sdm,'Tata cara mengajukan tukar shift, izin, dan cuti.','Ajukan lewat Pesan Internal ke manajer paling lambat H-2.\nSebutkan nama rekan pengganti.\nTukar shift berlaku setelah disetujui manajer.\nIzin mendadak wajib menelepon manajer.',@u_manajer,'published','internal',@u_manajer,NULL,1,52,TIMESTAMP(CURDATE() - INTERVAL 33 DAY, '10:30:00'),TIMESTAMP(CURDATE() - INTERVAL 33 DAY, '14:10:00')),
('Cara Mengganti Password MartOffice',@k_ti,'Langkah mengganti password akun pegawai.','Hubungi administrator untuk reset password.\nGunakan minimal 6 karakter.\nJangan berbagi akun dengan rekan kerja.',@u_admin,'published','internal',@u_admin,NULL,1,19,TIMESTAMP(CURDATE() - INTERVAL 31 DAY, '10:30:00'),TIMESTAMP(CURDATE() - INTERVAL 31 DAY, '14:10:00')),
('Cara Memasang Label Harga Promo',@k_prod,'Panduan mencetak dan memasang label promo agar tidak salah harga.','Ambil daftar promo dari pengumuman.\nCetak label dengan warna kuning.\nPasang H-1 sebelum promo berlaku.\nLepas label promo pada malam terakhir.',@u_dimas,'published','internal',@u_manajer,NULL,1,33,TIMESTAMP(CURDATE() - INTERVAL 28 DAY, '10:30:00'),TIMESTAMP(CURDATE() - INTERVAL 28 DAY, '14:10:00')),
('Menghitung Kas Kasir di Akhir Shift',@k_ops,'Cara mencocokkan uang di laci dengan transaksi tunai.','Buka menu Transaksi Saya dan filter metode Tunai.\nJumlahkan total tunai hari ini.\nHitung uang di laci dikurangi modal awal.\nLaporkan selisih ke manajer.',@u_staff,'published','internal',@u_manajer,NULL,1,45,TIMESTAMP(CURDATE() - INTERVAL 24 DAY, '10:30:00'),TIMESTAMP(CURDATE() - INTERVAL 24 DAY, '14:10:00')),
('Ide Bundling untuk Produk Kurang Laku',@k_prod,'Contoh paket bundling agar produk lambat laku ikut terjual.','Gabungkan produk lambat laku dengan produk terlaris.\nBeri harga paket sedikit lebih murah.\nLetakkan di rak ujung dekat kasir.',@u_staff,'published','internal',@u_manajer,NULL,1,12,TIMESTAMP(CURDATE() - INTERVAL 18 DAY, '10:30:00'),TIMESTAMP(CURDATE() - INTERVAL 18 DAY, '14:10:00')),
('Mengatasi Mesin EDC Gagal Transaksi',@k_ti,'Langkah cepat saat transaksi debit gagal.','Cek koneksi mesin.\nCoba ulang satu kali.\nJika tetap gagal, tawarkan QRIS atau tunai.',@u_dimas,'published','internal',@u_manajer,'Perlu dilengkapi nanti.',1,27,TIMESTAMP(CURDATE() - INTERVAL 15 DAY, '10:30:00'),TIMESTAMP(CURDATE() - INTERVAL 15 DAY, '14:10:00')),
('Menimbang Buah dan Sayur Curah',@k_prod,'Cara menimbang dan memberi label harga produk curah.','Nolkan timbangan sebelum dipakai.\nPilih kode produk.\nTempel label di kemasan.',@u_nadia,'published','internal',@u_manajer,NULL,1,0,TIMESTAMP(CURDATE() - INTERVAL 9 DAY, '10:30:00'),TIMESTAMP(CURDATE() - INTERVAL 9 DAY, '14:10:00')),
('Checklist Kebersihan Sebelum Toko Buka',@k_ops,'Daftar periksa kebersihan area penjualan setiap pagi.','Lantai disapu dan dipel.\nRak dilap.\nKeranjang belanja ditata.\nArea kasir dibersihkan.',@u_nadia,'menunggu_review','internal',NULL,NULL,1,0,TIMESTAMP(CURDATE() - INTERVAL 6 DAY, '10:30:00'),TIMESTAMP(CURDATE() - INTERVAL 6 DAY, '14:10:00')),
('Denah Penyimpanan Gudang',@k_ops,'Pembagian area gudang per kategori produk.','Area A: sembako.\nArea B: minuman.\nArea C: kebutuhan rumah.\nArea D: camilan.',@u_bagus,'menunggu_review','internal',NULL,NULL,1,0,TIMESTAMP(CURDATE() - INTERVAL 1 DAY, '10:30:00'),TIMESTAMP(CURDATE() - INTERVAL 1 DAY, '14:10:00')),
('Perhitungan Jam Lembur',@k_sdm,'Catatan cara menghitung lembur.','Lembur dihitung per jam.',@u_dimas,'ditolak','internal',@u_manajer,'Isi terlalu singkat, lengkapi dengan aturan dan contoh perhitungan.',1,0,TIMESTAMP(CURDATE() - INTERVAL 13 DAY, '10:30:00'),TIMESTAMP(CURDATE() - INTERVAL 13 DAY, '14:10:00'));
